// Affiliate ID configuration - REPLACE THIS WITH YOUR ACTUAL AMAZON ASSOCIATE ID
const AFFILIATE_ID = 'civilline20-21';

function getAffiliateLink(asin) {
    return `https://www.amazon.com/dp/${asin}?tag=${AFFILIATE_ID}`;
}

function formatPrice(price) {
    return '$' + price.toFixed(2);
}

function formatReviews(count) {
    if (count >= 1000) {
        return (count / 1000).toFixed(1) + 'K';
    }
    return count.toString();
}

function renderStars(rating) {
    const fullStars = Math.floor(rating);
    const hasHalf = rating % 1 >= 0.5;
    let stars = '';
    for (let i = 0; i < fullStars; i++) stars += '★';
    if (hasHalf) stars += '½';
    for (let i = fullStars + (hasHalf ? 1 : 0); i < 5; i++) stars += '☆';
    return stars;
}

function getProductsByCategory(category) {
    if (category === 'all') return productsData;
    return productsData.filter(p => p.category === category);
}

function getProductByAsin(asin) {
    return productsData.find(p => p.asin === asin);
}

function getCategories() {
    const cats = [...new Set(productsData.map(p => p.category))];
    return cats;
}

function searchProducts(query) {
    const q = query.toLowerCase();
    return productsData.filter(p => 
        p.name.toLowerCase().includes(q) || 
        p.desc.toLowerCase().includes(q) ||
        p.category.toLowerCase().includes(q)
    );
}
